\begin{equation}
    p_\star = \begin{cases}
        \min & f_0(x) + r(x)\\
        \mathrm{s.t.} & f_s(x) \leq 0 \qquad \forall s=1\dots m
    \end{cases}\label{eq:super-problem}
\end{equation}

where the functions $f_s\colon \mathcal{E}\rightarrow \mathbb{R}$, $s=0,\dots, m,$ are (strongly) convex but may be nonsmooth and not globally Lipschitz continuous and $r\colon \mathcal{E}\rightarrow \mathbb{R}\cup\{\infty\}$ is convex, closed, and simple, all defined over a finite-dimensional Euclidean space $\varSpace$. We will consider iteratively solving problems of this general form via a stochastic switching proximal subgradient method. This general method corresponds to the classic subgradient method when $r=0$ and $m=0$, the proximal subgradient method when $m=0$, and the switching subgradient method of~\cite{Polyak1967} when $r=0$. Formal assumptions and definitions are deferred to Section~\ref{sec:prelim}. 


$g_0(x)\in \partial f_0(x) := \{  g \mid f_0(y) \geq f_0(x) + \langle g , y-x \rangle \quad \forall y\in\varSpace\}$. Note when $f_0$ is $\mu$-strongly convex (that is, $f(x)-\frac{\mu}{2}\|x\|_2^2$ is convex), each subgradient $g_0(x)\in \partial f_0(x)$, provides a quadratic lower bound
\begin{equation}
    f_0(y) \geq f_0(x) + \langle g_0(x) , y-x \rangle +\frac{\mu}{2}\|y-x\|_2^2 \quad \forall y\in\varSpace \ .
\label{eq:subgradient-lower-bound}
\end{equation}

First, we allow for additive composite objectives $f_0+r$ for any {\color{blue} proper} closed convex $r\colon \varSpace\rightarrow \mathbb{R}\cup\{\infty\}$. We address this added term by assuming $r$ is sufficiently simple that its proximal operator
$ \mathrm{prox}_{\alpha_k, r}(z) := \argmin_x\left\{r(x) + \frac{1}{2\alpha_k}\|x-z\|_2^2\right\} $
can be evaluated at each iteration. For example, if $r$ is an indicator function for a closed convex constraint set, its proximal operator corresponds to projection onto that set. Since $r(x) + \frac{1}{2\alpha_k}\|x-z\|_2^2$ is strongly convex, it has a unique minimizer described by the following equivalence
\begin{equation}
    z_+ = \mathrm{prox}_{\alpha_k, r}(z) \quad \iff \quad \frac{1}{\alpha_k}(z-z_+)\in \partial r(z_+) \ . \label{eq:proximal-equivalence}
\end{equation}

Second, we allow for $m$ strongly convex functional constraints $f_s(x)\leq 0$ for $s=1,\dots, m$. We address these added terms by ``switching'': Given a current iterate $x$, only one function $f_{s(x)}$ will be considered in that iteration. This function will be chosen as $s(x)=0$ if $x$ is feasible (that is, $f_s(x)\leq 0$ for all $s=1\dots m$), otherwise $s(x)$ can be chosen generically as any violated constraint $f_{s(x)}(x)>0$.
Third, we allow for stochasticity in our subgradient oracles for each function, denoted by $g_s(x;\xi)$ such that $\mathbb{E}_\xi g_{s}(x;\xi) \in \partial f_{s}(x)$. Note this trivially captures deterministic methods by selecting $g_s(x;\xi)$ constant with respect to $\xi$.


As a primal algorithm, consider the {\it Stochastic Switching Proximal Subgradient Method} with stepsizes $\alpha_k>0$ and sequence of iterates $\{x_k\}$ defined by
\begin{equation}\label{eq:super-primal-method}
    x_{k+1} = \begin{cases}
        \mathrm{prox}_{\alpha_k, r} (x_k-\alpha_k g_{0}(x_k;\xi_k)) & \text{if $x_k$ is feasible}\\
        x_k-\alpha_k g_{s(x_k)}(x_k;\xi_k) & \text{otherwise.}        
    \end{cases}
\end{equation}

for i.i.d.~sampled $\xi_k$. Throughout, we always assume $\alpha_k>0$, strictly.


\begin{align*}
    p_\star &= \min_{x\in\varSpace}\max_{u_1,\dots u_s\geq 0} f_0(x) + \sum_{s=1}^m u_sf_s(x) + r(x) \\
    &=\min_{x\in\varSpace}\max_{\substack{y_0,\dots, y_{T}\in\varSpace\\ \lambda_0,\dots, \lambda_{T-1}\geq 0 \\ \sum_{k<T\colon s(y_k)=0} \lambda_k >0\\ n_{k+1}\in\partial r(y_{k+1})}} \mathbb{E}_{\xi}\Bigg(\sum_{s=0}^m\sum_{\substack{k<T \\ s(y_k)=s}} \lambda_k\left(f_{s(y_k)}(y_k) + \langle g_{s(y_k)}(y_k; \xi_k), x-y_k \rangle + \frac{\mu}{2}\|x-y_k\|_2^2\right)\\
    &\qquad\qquad\qquad\qquad\qquad\qquad +\sum_{\substack{k<T\\ s(y_k)=0}} \lambda_k\left(r(y_{k+1}) + \langle n_{k+1}, x - y_{k+1}\rangle\right)\Bigg)\frac{1}{\sum_{k<T\colon s(y_k)=0} \lambda_k}
\end{align*}

As a dual algorithm, consider the following {\it Stochastic Lagrangian Proximal Dual Averaging} with dual weights $\lambda_k>0$ and regularization parameters $\beta_k\geq 0$. Throughout, we always assume $\lambda_k>0$, strictly. Its sequence of iterates $\{y_k\}$ based on i.i.d.~sampled $\xi_k$ is defined as follows: At iteration $k$, construct the following (unnormalized) aggregations for each function based on the previous $k-1$ iterations as


where $n_{i+1} = \frac{-1}{\lambda_i}(\nabla M^{(i-1)}(y_{i+1}) + \lambda_i(g_0(y_i;\xi_i) +\mu(y_{i+1}-y_i)) + \beta_i(y_{i+1} - y_0)) \in \partial r(y_{i+1})$ (see Lemma~\ref{lem:Mk-minimization} for verification of this subdifferential containment).
At iteration $k=0$, these empty summations are understood to take value zero.
Then, based on the switching selection $s(y_k)$, a new weighted model is constructed as
$$ U^{(k)}(y) := \begin{cases} \lambda_k\left(f_{0}(y_k) + \langle g_0(y_k;\xi_k), y-y_k\rangle + \frac{\mu}{2}\|y-y_k\|_2^2 + r(y)\right) & \text{if $y_k$ is feasible}\\
\lambda_k\left(f_{s(y_k)}(y_k) + \langle g_{s(y_k)}(y_k;\xi_k), y-y_k\rangle + \frac{\mu}{2}\|y-y_k\|_2^2\right) & \text{otherwise.}
\end{cases} $$

The Lagrangian proximal dual averaging method then iterates by minimizing the aggregation of past models $M^{(k-1)}$ plus the new model $U^{(k)}$ (and an optional extra regularization term)
\begin{equation}\label{eq:super-dual-method}
    y_{k+1} = \argmin\left\{M^{(k-1)}(y) + U^{(k)}(y) +\frac{\beta_k}{2}\|y-y_0\|_2^2 \right\} \ .
\end{equation}

\noindent {\bf Assumption A.} The functions $f_s$ for $s=0\dots m$ are each $\mu>0$-strongly convex.\\
\noindent {\bf Assumption B.} There exists some $x_\mathtt{SL} \in \mathrm{dom\ }\partial r$ with $f_s(x_\mathtt{SL}) <0$ for all 
 $s = 1\dots m$.


Note strong convexity ensures there exists a unique minimizer $x_\mathtt{OPT} \in \mathrm{dom\ }\partial r$ of~\eqref{eq:super-problem}. These two points $x_\mathtt{OPT},x_\mathtt{SL} \in \mathrm{dom\ }\partial r$ serve as important references that our analysis is done with respect to. We fix two subgradients of $r$ at these points: The subgradient $n_{x_\mathtt{OPT}}\in \partial r(x_\mathtt{OPT})$ is chosen such that $f_0(x) + r(x_\mathtt{OPT}) + \langle n_{x_\mathtt{OPT}}, x-x_\mathtt{OPT}\rangle$ is minimized over $f_s(x)\leq 0$ at $x_\mathtt{OPT}$ for all $ s=1\ldots m$. The subgradient $n_{x_\mathtt{SL}} \in \partial r(x_\mathtt{SL})$ can be chosen freely. %When $r$ is an indicator function for a closed convex set, $n_{x_\mathtt{SL}}=0$ is a nice simplifying choice.

These two reference subgradients of $r$ facilitate considering two lower bounds of the objective $f_0+r$ for either $y\in\{x_{\mathtt{OPT}}, x_{\mathtt{SL}}\}$, denoted by
$$ h_{y}(x) := f_0(x) + r(y) + \langle n_{y}, x-y\rangle \ . $$

At each iteration $k$, we denote the relative difference between $x_k$ and $y\in\{x_{\mathtt{OPT}}, x_{\mathtt{SL}}\}$ in (relaxed) objective value or feasibility on the selected constraint function $f_{s(x_k)}$ by
\begin{align}
    \delta_k(y) &:=\begin{cases}
        h_y(x_k) - h_y(y) & \mathrm{if\ } x_k \mathrm{\ is\ feasible}\\
        f_{s(x_k)}(x_k) - f_{s(x_k)}(y) & \mathrm{otherwise.}
    \end{cases}\label{eq:delta_k-definition}
\end{align}

The sign of $\delta_k(y)$ may vary. If $y = x_{\mathtt{OPT}}$, then $\delta_k(x_\mathtt{OPT})$ is nonnegative, being lower bounded by the level of suboptimality or current infeasibility
$$ \delta_k(x_\mathtt{OPT}) \geq \begin{cases}
        h_{x_\mathtt{OPT}}(x_k) - p_\star & \mathrm{if\ } x_k \mathrm{\ is\ feasible}\\
        f_{s(x_k)}(x_k) & \mathrm{otherwise}
    \end{cases} \ \geq 0 \ . $$
When $y = x_{\mathtt{SL}}$ and $x_k$ is feasible, $\delta_k(y)$ may be negative but is bounded below by
$$ \delta_k(x_\mathtt{SL}) \geq \inf h_{x_{\mathtt{SL}}} -h_{x_{\mathtt{SL}}}(x_{\mathtt{SL}}) > -\infty \ . $$ When $y = x_{\mathtt{SL}}$ and $x_k$ is infeasible, $\delta_k(y)$ is strictly positive, being bounded below by $$\delta_k(x_\mathtt{SL}) \geq 0-\max_{s=1\dots m} f_s(x_\mathtt{SL}) >0 \ . $$


\noindent {\bf Assumption C.} For both $y\in\{x_{\mathtt{OPT}}, x_{\mathtt{SL}}\}$, there exist constants $L_0$, $L_1{\color{blue}\geq 0}$ such that every iterate $x_k$ has
\begin{equation}\label{eq:NonLipschitz-condition}
    \begin{cases}
        x_k \mathrm{\ is\ feasible} & \implies \mathbb{E}_{\xi_k}\|g_0(x_k;\xi_k) + n_{y}\|_2^2 \leq L_0^2 + L_1\delta_k(y)\\
        x_k \mathrm{\ is\ not\ feasible} & \implies \mathbb{E}_{\xi_k}\|g_{s(x_k)}(x_k;\xi_k)\|_2^2 \leq L_0^2 + L_1\delta_k(y) \ . 
    \end{cases}
\end{equation}

To understand and bound such behaviors, we introduce the following two constants, dependent on the choice of stepsizes $\alpha_k$ and associated dual weights $\lambda_k$,
\begin{align}
    T_0 &:= \sup\left\{ k\in\{0,1,2\dots\} \mid L_1\alpha_k > 1\right\} \ ,\label{eq:T0} \\
    C_0 &:= \sum_{k=0}^{T_0}\lambda_k \max\left\{L_1 \alpha_k - 1, 0 \right\}\max\{\mathbb{E}_\xi\delta_k(x_\mathtt{OPT}), \mathbb{E}_\xi\delta_k(x_\mathtt{SL})\} \ . \label{eq:C0}
\end{align}

We prove a uniform convergence guarantee in terms of the primal gap
\begin{equation} \label{eq:primalgap-definition}
    \mathtt{primal\mbox{-}gap}_T := \frac{\sum_{k< T: s(x_k)=0} \lambda_k h_{x_\mathtt{OPT}}(x_k)}{\sum_{k< T: s(x_k)=0} \lambda_k } - p_\star \ ,
\end{equation}

which utilizes a combination of the feasible objective values seen, the dual gap
\begin{equation} \label{eq:dualgap-definition}
    \mathtt{dual\mbox{-}gap}_T := p_\star - \inf \frac{M^{(T-1)}}{\sum_{k< T: s(x_k)=0} \lambda_k }\ ,
\end{equation}

which utilizes a combination of the subgradient lower bounds seen, and the distance to optimal.
For the primal and dual gaps to be well-defined, at least one feasible iterate must have been seen (i.e., $\sum_{k< T: s(x_k)=0} \lambda_k >0$). Our assumptions facilitate a bound on how long it takes for this to occur. We show the expected fraction of the dual weight that occurs on iterations with a feasible iterate (i.e., $s(x_k)=0$) is bounded below.


Once a feasible iterate occurs, our primal and dual convergence measures are well-defined. Alternatively, one could assume the initialization $x_0$ is feasible to ensure these quantities are well-defined. In either case, Subsection~\ref{subsec:proof-main-result} proves the following primal-dual convergence guarantee as our main result.


\begin{equation} \label{eq:Rk-definition}
R_k(y) := \left(\frac{\mu}{2}\sum_{i=0}^{{k-1}} \lambda_i\right) \mathbb{E}_\xi\|x_k-y\|_2^2
\end{equation}

To simplify notations, throughout our analysis, we denote $g_k = g_{s(x_k)}(x_k;\xi_k)$ and $w_k = \mu\sum_{i=0}^{k} \lambda_i$ (with the convention that $w_{-1}=0$ as the given summation is empty).


\begin{equation} \label{eq:Dk-definition}
    D_k := \mathbb{E}_\xi\left[\left(\sum_{i< k:s(x_i)=0} \lambda_i\right) p_\star - \inf M^{(k-1)}\right] \ .
\end{equation}

