\begin{theorem}\label{thm:super-rate}
    Under Assumptions A-C, for any primal stepsizes $\alpha_k>0$ and dual weights $\lambda_k>0$ satisfying~\eqref{eq:alpha-lambda} with $\bar\beta=0$, the stochastic switching proximal subgradient method~\eqref{eq:super-primal-method} has
    \begin{align*}
        &\mathbb{E}_\xi \left[\left(\frac{\sum_{k< T: s(x_k)=0} \lambda_k}{\sum_{k=0}^{T-1} \lambda_k}\right)\left(\mathtt{primal\mbox{-}gap}_T + \mathtt{dual\mbox{-}gap}_T\right) + \frac{\mu}{2}\|x_{T}-x_\mathtt{OPT}\|_2^2\right] \\
        &\qquad \qquad \leq \frac{ L_0^2\sum_{k=0}^{T-1}\lambda_k\alpha_k + C_0}{\sum_{k=0}^{T-1}\lambda_k} \ .
    \end{align*}
\end{theorem}

