    y_{k+1} &= y_0 + \frac{\sum_{i=0}^k\lambda_i\mu(y_i-y_0)-\sum_{i=0}^k\lambda_i\bar g_i}{\sum_{i=0}^k\lambda_i\mu+\bar\beta}\\
    &= y_0 -\frac{\sum_{i=0}^{k} \lambda_{i}\mu\left( \sum_{t=0}^{i-1} \frac{\lambda_{t} \bar g_t}{\sum_{s=0}^{t}\lambda_{s}\mu + \bar \beta} \right) + \sum_{i=0}^{k}\lambda_i \bar g_i}{\sum_{i=0}^{k}\lambda_i\mu + \bar\beta}\\
    &= y_0 -\frac{\sum_{t=0}^{k-1} \lambda_t \bar g_t\frac{\sum_{i=t+1}^k \mu\lambda_i}{\sum_{i=0}^t \mu\lambda_{{\color{blue} i}} +\bar\beta} + \sum_{i=0}^{k}\lambda_i \bar g_i}{\sum_{i=0}^{k}\lambda_i\mu+\bar\beta}\\
    &= y_0 -\frac{\sum_{t=0}^{k-1} \lambda_t \bar g_t\left(\frac{\sum_{i=t+1}^k \mu\lambda_i}{\sum_{i=0}^t \mu\lambda_{{\color{blue} i}} +\bar\beta}+1\right)}{\sum_{i=0}^{k}\lambda_i\mu+\bar\beta} - \frac{\lambda_k \bar g_k}{\sum_{i=0}^{k}\lambda_i\mu + \bar\beta}\\
