\begin{lemma}\label{lem:switching-proximal-primal-induction}
    Under Assumptions A-C, the switching proximal subgradient method~\eqref{eq:super-primal-method} with $\alpha_k=\lambda_k/\mu\sum_{i=0}^k\lambda_i$ has for either $y\in\{x_{\mathtt{OPT}}, x_{\mathtt{SL}}\}$
    $$R_{k+1}(y) \leq R_k(y) - \frac{\lambda_k}{2}\left(\left(2-L_1\alpha_k\right)\mathbb{E}_\xi\delta_{k}(y) - L_0^2\alpha_k\right) \ . $$
\end{lemma}

\begin{proof}
    This proof follows a standard analysis technique, directly expanding the definition of $R_{k+1}(y)$. First, suppose $x_k$ is feasible. Then
    \begin{align*}
    R_{k+1}(y) &= \frac{w_k}{2}\mathbb{E}_\xi\|\mathrm{prox}_{\alpha_k,r}(x_k - \alpha_k g_k) - \mathrm{prox}_{\alpha_k,r}(y +\alpha_k n_{y})\|_2^2\\
    &\leq \frac{w_k}{2}\mathbb{E}_\xi\|x_k - \alpha_k(g_k+n_{y}) - y\|_2^2\\
    &= \frac{w_k}{2}\mathbb{E}_\xi\|x_k-y\|_2^2 - \lambda_k\mathbb{E}_\xi\langle g_k + n_{y}, x_k-y\rangle +\frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{y}\|_2^2\\
    &\leq \frac{w_k}{2}\mathbb{E}_\xi\|x_k-y\|_2^2 - \lambda_k\mathbb{E}_\xi(h_y(x_k)-h_y(y)+\frac{\mu}{2}\|x_k - y\|_2^2) + \frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{y}\|_2^2\\
    &= R_k(y) - \lambda_k\mathbb{E}_\xi\delta_k(y)+\frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{y}\|_2^2
   \end{align*}
    where the first line uses that $\mathrm{prox}_{\alpha_k,r}(y +\alpha_k n_{y}) = y$, the second uses the nonexpansiveness of the proximal operator~\cite[Proposition 12.19]{RockWets98}, the third factors the norm squared and uses $\alpha_k = \lambda_k/w_k$, the fourth uses the strong convexity of $h_y$, {\color{blue} and the fifth follows from definitions as $R_k(y) = \frac{w_k - \lambda_k\mu}{2}\mathbb{E}_\xi\|x_k-y\|_2^2$ and $\delta_k(y)=h_y(x_k)-h_y(y)$}.
    Then, applying the bound~\eqref{eq:NonLipschitz-condition} gives the claim.
    Similarly, supposing $x_k$ is infeasible,
    \begin{align*}
    R_{k+1}(y) &= \frac{w_k}{2}\mathbb{E}_\xi\|x_k - \alpha_k g_k - y\|_2^2\\
    &= \frac{w_k}{2}\mathbb{E}_\xi\|x_k-y\|_2^2 - \lambda_k\mathbb{E}_\xi\langle g_k, x_k-y\rangle + \frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k\|_2^2\\
    &\leq \frac{w_k}{2}\mathbb{E}_\xi\|x_k-y\|_2^2- \lambda_k\mathbb{E}_\xi(f_{s(x_k)}(x_k)-f_{s(x_k)}(y) +\frac{\mu}{2}\|x_k - y\|_2^2) + \frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k\|_2^2\\
    &= R_k(y) - \lambda_k\mathbb{E}_\xi\delta_k(y)+\frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k\|_2^2 
   \end{align*}
   using strong convexity of $f_{s(x_k)}$. Applying~\eqref{eq:NonLipschitz-condition} completes the proof.
\end{proof}

\begin{lemma}\label{lem:switching-proximal-dual-induction}
    Under Assumptions A-C, the switching proximal subgradient method~\eqref{eq:super-primal-method} with $\alpha_k=\lambda_k/\mu\sum_{i=0}^k\lambda_i$ has
     $$ D_{k+1} \leq D_k - \frac{\lambda_k}{2}\begin{cases}
         \left(2-L_1\alpha_k\right)\mathbb{E}_\xi\delta_{k}(x_\mathtt{OPT}) - L_0^2\alpha_k & \text{if } x_k \text{ is feasible}\\
         {\color{blue}\left(2-L_1\alpha_k\right)\mathbb{E}_\xi\delta_{k}(x_\mathtt{OPT}) + 2\mathbb{E}_\xi f_{s(x_k)}(x_\mathtt{OPT}) - L_0^2\alpha_k} & \text{otherwise.}
     \end{cases} $$
\end{lemma}

\begin{proof}
Observe that one can rewrite $M^{(k)}(x) = Q_1(x) + Q_2(x)$ as the sum of two quadratics where $Q_1(x) = M^{(k-1)}(x)$ and $Q_2$ depends on whether $x_k$ is feasible. In the notation of Lemma~\ref{lem:quad-calc}, Lemmas~\ref{lem:Mk-minimization} {\color{blue} and~\ref{lem:standard-quadratic}} ensure $Q_1$ has $a_1 = \inf M^{(k-1)}$, $b_1 = \mu\sum_{i=0}^{k-1}\lambda_i$, and $z_1 = x_{k}${\color{blue}, since $\bar \beta = 0$ here}. To determine $Q_2$, first suppose $x_k$ is feasible. Then we have
$$Q_2(x) = \lambda_k \left(f_{0}(x_k) + \langle g_k, x-x_k \rangle +\frac{\mu}{2}\|x - x_k\|_2^2 + r(x_{k+1}) + \langle n_{k+1}, x-x_{k+1}\rangle\right) \ . $$
This quadratic can be written in the form $Q_2(z) = a_2 + \frac{b_2}{2}\|z-z_2\|_2^2$ with
\begin{align*}
    a_2 &= \lambda_k\left(f_0(x_k) + r(x_{k+1}) + \alpha_k\langle n_{k+1}, g_{k}+n_{k+1}\rangle - \frac{1}{2\mu}\|g_k + n_{k+1}\|_2^2 \right)\ , \\
    b_2 &= \mu\lambda_k \ , \qquad z_2 = x_k - \frac{g_k+n_{k+1}}{\mu} \ . 
\end{align*}
By Lemma~\ref{lem:quad-calc}, the expected minimum value of the updated model $\mathbb{E}_\xi \inf M^{(k)}$ is
\begin{align*}
    &\mathbb{E}_\xi \inf M^{(k-1)} + \lambda_k \mathbb{E}_\xi\Bigg(f_0(x_k) + r(x_{k+1}) + \alpha_k \langle n_{k+1}, g_{k}+n_{k+1}\rangle - \frac{1}{2\mu}\|g_k + n_{k+1}\|_2^2\\
    & \qquad\qquad\qquad\qquad\qquad + \frac{\sum_{i=0}^{k-1}\lambda_i }{2\mu \sum_{i=0}^k \lambda_i}\left\|g_{k}+n_{k+1}\right\|_2^2\Bigg) \ . 
\end{align*}
From this, we conclude the lower bound
\begin{align*}
    \mathbb{E}_\xi \inf M^{(k)} &\geq \mathbb{E}_\xi \inf M^{(k-1)} + \lambda_k \mathbb{E}_\xi\Bigg(f_0(x_k) + r(x_\mathtt{OPT}) + \langle n_{x_\mathtt{OPT}}, x_{k+1}-x_\mathtt{OPT}\rangle  \\
    & \quad + \alpha_k \langle n_{k+1}, g_{k}+n_{k+1}\rangle - \frac{1}{2\mu}\|g_k + n_{k+1}\|_2^2 + \frac{\sum_{i=0}^{k-1}\lambda_i }{2\mu \sum_{i=0}^k \lambda_i}\left\|g_{k}+n_{k+1}\right\|_2^2\Bigg)\\
    &= \mathbb{E}_\xi \inf M^{(k-1)} + \lambda_k \mathbb{E}_\xi\Bigg(\delta_k(x_\mathtt{OPT}) + p_\star + \langle n_{x_\mathtt{OPT}}, -\alpha_k(g_k + n_{k+1})\rangle  \\
    & \quad + \alpha_k \langle n_{k+1}, g_{k}+n_{k+1}\rangle - \frac{\alpha_k}{2}\|g_k + n_{k+1}\|_2^2\Bigg)\\
    &= \mathbb{E}_\xi\inf M^{(k-1)} + \lambda_k \left(\mathbb{E}_\xi\delta_k(x_\mathtt{OPT}) + p_\star - \frac{\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{x_\mathtt{OPT}}\|_2^2 { \color{blue} + \frac{\alpha_k}{2}\|n_{k+1}-n_{x_\mathtt{OPT}} \|_2^2}\right)\\
    & {\color{blue} \geq \mathbb{E}_\xi\inf M^{(k-1)} + \lambda_k \left(\mathbb{E}_\xi\delta_k(x_\mathtt{OPT}) + p_\star - \frac{\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{x_\mathtt{OPT}}\|_2^2\right)}
\end{align*}
where the first inequality lower bounds $r(x_{k+1})$ by $r(x_\mathtt{OPT}) + \langle n_{x_\mathtt{OPT}}, x_{k+1}-x_\mathtt{OPT}\rangle$, the first equality applies the definitions of $\delta_k(x_\mathtt{OPT})$ in~\eqref{eq:delta_k-definition}, $\alpha_k$ in~\eqref{eq:alpha-lambda} {\color{blue} with $\bar \beta = 0$, and that $x_{k+1}-x_k=-\alpha_k(g_k+n_{k+1})$}, and the {\color{blue} second} equality combines and simplifies terms.
In terms of $D_k = \mathbb{E}_\xi[\sum_{i< k:s(x_i)=0} \lambda_i p_\star - \inf M^{(k-1)}]$, this gives the following 
recurrence
$$ D_{k+1} \leq D_k - \lambda_k \mathbb{E}_\xi\delta_k(x_\mathtt{OPT}) + \frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{x_\mathtt{OPT}}\|_2^2 \ . $$
Applying~\eqref{eq:NonLipschitz-condition} gives the claim in this case.
Now suppose $x_k$ is infeasible. Then, noting $Q_2$ minimizes at $x_k - \frac{g_{k}}{\mu}$, Lemma~\ref{lem:standard-quadratic} ensures
\begin{align*}
    Q_2(x) &= \lambda_k\left(f_{s(x_k)}(x_k) - \frac{1}{2\mu}\|g_k \|_2^2 + \frac{\mu}{2}\left\|x - \left(x_k - \frac{g_{k}}{\mu}\right)\right\|_2^2\right) \ .
\end{align*}
