$g_0(x)\in \partial f_0(x) := \{  g \mid f_0(y) \geq f_0(x) + \langle g , y-x \rangle \quad \forall y\in\varSpace\}$. Note when $f_0$ is $\mu$-strongly convex (that is, $f(x)-\frac{\mu}{2}\|x\|_2^2$ is convex), each subgradient $g_0(x)\in \partial f_0(x)$, provides a quadratic lower bound
\begin{equation}
    f_0(y) \geq f_0(x) + \langle g_0(x) , y-x \rangle +\frac{\mu}{2}\|y-x\|_2^2 \quad \forall y\in\varSpace \ .
\label{eq:subgradient-lower-bound}
\end{equation}

First, we allow for additive composite objectives $f_0+r$ for any {\color{blue} proper} closed convex $r\colon \varSpace\rightarrow \mathbb{R}\cup\{\infty\}$. We address this added term by assuming $r$ is sufficiently simple that its proximal operator
$ \mathrm{prox}_{\alpha_k, r}(z) := \argmin_x\left\{r(x) + \frac{1}{2\alpha_k}\|x-z\|_2^2\right\} $
can be evaluated at each iteration. For example, if $r$ is an indicator function for a closed convex constraint set, its proximal operator corresponds to projection onto that set. Since $r(x) + \frac{1}{2\alpha_k}\|x-z\|_2^2$ is strongly convex, it has a unique minimizer described by the following equivalence
\begin{equation}
    z_+ = \mathrm{prox}_{\alpha_k, r}(z) \quad \iff \quad \frac{1}{\alpha_k}(z-z_+)\in \partial r(z_+) \ . \label{eq:proximal-equivalence}
\end{equation}

As a primal algorithm, consider the {\it Stochastic Switching Proximal Subgradient Method} with stepsizes $\alpha_k>0$ and sequence of iterates $\{x_k\}$ defined by
\begin{equation}\label{eq:super-primal-method}
    x_{k+1} = \begin{cases}
        \mathrm{prox}_{\alpha_k, r} (x_k-\alpha_k g_{0}(x_k;\xi_k)) & \text{if $x_k$ is feasible}\\
        x_k-\alpha_k g_{s(x_k)}(x_k;\xi_k) & \text{otherwise.}        
    \end{cases}
\end{equation}

\begin{align*}
    p_\star &= \min_{x\in\varSpace}\max_{u_1,\dots u_s\geq 0} f_0(x) + \sum_{s=1}^m u_sf_s(x) + r(x) \\
    &=\min_{x\in\varSpace}\max_{\substack{y_0,\dots, y_{T}\in\varSpace\\ \lambda_0,\dots, \lambda_{T-1}\geq 0 \\ \sum_{k<T\colon s(y_k)=0} \lambda_k >0\\ n_{k+1}\in\partial r(y_{k+1})}} \mathbb{E}_{\xi}\Bigg(\sum_{s=0}^m\sum_{\substack{k<T \\ s(y_k)=s}} \lambda_k\left(f_{s(y_k)}(y_k) + \langle g_{s(y_k)}(y_k; \xi_k), x-y_k \rangle + \frac{\mu}{2}\|x-y_k\|_2^2\right)\\
    &\qquad\qquad\qquad\qquad\qquad\qquad +\sum_{\substack{k<T\\ s(y_k)=0}} \lambda_k\left(r(y_{k+1}) + \langle n_{k+1}, x - y_{k+1}\rangle\right)\Bigg)\frac{1}{\sum_{k<T\colon s(y_k)=0} \lambda_k}
\end{align*}

$$ U^{(k)}(y) := \begin{cases} \lambda_k\left(f_{0}(y_k) + \langle g_0(y_k;\xi_k), y-y_k\rangle + \frac{\mu}{2}\|y-y_k\|_2^2 + r(y)\right) & \text{if $y_k$ is feasible}\\
\lambda_k\left(f_{s(y_k)}(y_k) + \langle g_{s(y_k)}(y_k;\xi_k), y-y_k\rangle + \frac{\mu}{2}\|y-y_k\|_2^2\right) & \text{otherwise.}
\end{cases} $$

The Lagrangian proximal dual averaging method then iterates by minimizing the aggregation of past models $M^{(k-1)}$ plus the new model $U^{(k)}$ (and an optional extra regularization term)
\begin{equation}\label{eq:super-dual-method}
