    \end{cases}\label{eq:delta_k-definition}
\end{align}

\noindent {\bf Assumption C.} For both $y\in\{x_{\mathtt{OPT}}, x_{\mathtt{SL}}\}$, there exist constants $L_0$, $L_1{\color{blue}\geq 0}$ such that every iterate $x_k$ has
\begin{equation}\label{eq:NonLipschitz-condition}
