    \end{cases}
\end{equation}

To understand and bound such behaviors, we introduce the following two constants, dependent on the choice of stepsizes $\alpha_k$ and associated dual weights $\lambda_k$,
\begin{align}
    T_0 &:= \sup\left\{ k\in\{0,1,2\dots\} \mid L_1\alpha_k > 1\right\} \ ,\label{eq:T0} \\
    C_0 &:= \sum_{k=0}^{T_0}\lambda_k \max\left\{L_1 \alpha_k - 1, 0 \right\}\max\{\mathbb{E}_\xi\delta_k(x_\mathtt{OPT}), \mathbb{E}_\xi\delta_k(x_\mathtt{SL})\} \ . \label{eq:C0}
\end{align}

We prove a uniform convergence guarantee in terms of the primal gap
\begin{equation} \label{eq:primalgap-definition}
    \mathtt{primal\mbox{-}gap}_T := \frac{\sum_{k< T: s(x_k)=0} \lambda_k h_{x_\mathtt{OPT}}(x_k)}{\sum_{k< T: s(x_k)=0} \lambda_k } - p_\star \ ,
\end{equation}

which utilizes a combination of the feasible objective values seen, the dual gap
\begin{equation} \label{eq:dualgap-definition}
