\end{equation}

\begin{equation} \label{eq:Rk-definition}
R_k(y) := \left(\frac{\mu}{2}\sum_{i=0}^{{k-1}} \lambda_i\right) \mathbb{E}_\xi\|x_k-y\|_2^2
\end{equation}

\begin{equation} \label{eq:Dk-definition}
    D_k := \mathbb{E}_\xi\left[\left(\sum_{i< k:s(x_i)=0} \lambda_i\right) p_\star - \inf M^{(k-1)}\right] \ .
\end{equation}

\begin{theorem}\label{thm:super-rate}
    Under Assumptions A-C, for any primal stepsizes $\alpha_k>0$ and dual weights $\lambda_k>0$ satisfying~\eqref{eq:alpha-lambda} with $\bar\beta=0$, the stochastic switching proximal subgradient method~\eqref{eq:super-primal-method} has
