    &= \mathbb{E}_\xi \inf M^{(k-1)} + \lambda_k \mathbb{E}_\xi\Bigg(\delta_k(x_\mathtt{OPT}) + p_\star + \langle n_{x_\mathtt{OPT}}, -\alpha_k(g_k + n_{k+1})\rangle  \\
    & \quad + \alpha_k \langle n_{k+1}, g_{k}+n_{k+1}\rangle - \frac{\alpha_k}{2}\|g_k + n_{k+1}\|_2^2\Bigg)\\
    &= \mathbb{E}_\xi\inf M^{(k-1)} + \lambda_k \left(\mathbb{E}_\xi\delta_k(x_\mathtt{OPT}) + p_\star - \frac{\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{x_\mathtt{OPT}}\|_2^2 { \color{blue} + \frac{\alpha_k}{2}\|n_{k+1}-n_{x_\mathtt{OPT}} \|_2^2}\right)\\
    & {\color{blue} \geq \mathbb{E}_\xi\inf M^{(k-1)} + \lambda_k \left(\mathbb{E}_\xi\delta_k(x_\mathtt{OPT}) + p_\star - \frac{\alpha_k}{2}\mathbb{E}_\xi\|g_k+n_{x_\mathtt{OPT}}\|_2^2\right)}
\end{align*}
where the first inequality lower bounds $r(x_{k+1})$ by $r(x_\mathtt{OPT}) + \langle n_{x_\mathtt{OPT}}, x_{k+1}-x_\mathtt{OPT}\rangle$, the first equality applies the definitions of $\delta_k(x_\mathtt{OPT})$ in~\eqref{eq:delta_k-definition}, $\alpha_k$ in~\eqref{eq:alpha-lambda} {\color{blue} with $\bar \beta = 0$, and that $x_{k+1}-x_k=-\alpha_k(g_k+n_{k+1})$}, and the {\color{blue} second} equality combines and simplifies terms.

Now suppose $x_k$ is infeasible. Then, noting $Q_2$ minimizes at $x_k - \frac{g_{k}}{\mu}$, Lemma~\ref{lem:standard-quadratic} ensures
\begin{align*}
    Q_2(x) &= \lambda_k\left(f_{s(x_k)}(x_k) - \frac{1}{2\mu}\|g_k \|_2^2 + \frac{\mu}{2}\left\|x - \left(x_k - \frac{g_{k}}{\mu}\right)\right\|_2^2\right) \ .
\end{align*}

Then by Lemma~\ref{lem:quad-calc}, the expected minimum value of the updated model $\mathbb{E}_\xi \inf M^{(k)}$ is given by
\begin{align*}
    &\mathbb{E}_\xi\inf  M^{(k-1)} + \lambda_k\mathbb{E}_\xi\left(f_{s(x_k)}(x_k) - \frac{1}{2\mu}\|g_k \|_2^2\right) + \frac{\lambda_k\sum_{i=0}^{k-1}\lambda_i }{{\color{blue} 2}\mu \sum_{i=0}^k \lambda_i}\mathbb{E}_\xi\left\|g_{k}\right\|_2^2 \\
    &= \mathbb{E}_\xi\inf M^{(k-1)} + \lambda_k\mathbb{E}_\xi f_{s(x_k)}(x_k) - \frac{\lambda_k\alpha_k}{2}\mathbb{E}_\xi\|g_k\|_2^2 \ . 
\end{align*}

{\color{blue}
In terms of $D_k = \mathbb{E}_\xi[\sum_{i< k:s(x_i)=0} \lambda_i p_\star - \mathbb{E}_\xi\inf M^{(k-1)}]$, this gives the recurrence
$$ D_{k+1} = D_k - \lambda_k \mathbb{E}_\xi\left[\delta_{k}(x_\mathtt{OPT}) + f_{s(x_k)}(x_{\mathtt{OPT}})\right] + \frac{\lambda_k\alpha_k}{2} \mathbb{E}_\xi\|g_k\|_2^2 \ . $$
Bounding $\mathbb{E}_\xi\|g_k\|_2^2$ by~\eqref{eq:NonLipschitz-condition} gives the claim in this last case.
}

\begin{theorem} \label{thm:super-equivalence}
    Let $\{x_k\}$ be the sequence of iterates of the primal method~\eqref{eq:super-primal-method} with stepsizes $\alpha_k>0$ and $\{y_k\}$ be the sequence of iterates of the dual method~\eqref{eq:super-dual-method} for some $\lambda_k,\beta_k,\mu\geq 0$. If $x_0=y_0$, $\beta_k=\bar\beta\geq 0$ is constant, and
    \begin{equation}
        \alpha_k = \frac{\lambda_k}{\mu\sum_{i=0}^k\lambda_i + \bar\beta}\ , \label{eq:alpha-lambda}
    \end{equation} 
    then these methods are equivalent, that is $x_k=y_k$.
\end{theorem}

Let $\{x_k\}$ be the sequence of iterates of the primal method~\eqref{eq:super-primal-method} with stepsizes $\alpha_k>0$ and $\{y_k\}$ be the sequence of iterates of the dual method~\eqref{eq:super-dual-method} for some $\lambda_k,\beta_k,\mu\geq 0$. If $x_0=y_0$, $\beta_k=\bar\beta\geq 0$ is constant, and
\begin{equation}
    \alpha_k = \frac{\lambda_k}{\mu\sum_{i=0}^k\lambda_i + \bar\beta}\ , \label{eq:alpha-lambda}
\end{equation}

\begin{proof}
        We prove this by inductively showing that $x_k=y_k$ and for any iteration with $s(x_k)=0$ that $n_{k+1} = \frac{1}{\alpha_k}(x_k-\alpha_k g_{0}(x_k;\xi_k) -x_{k+1})$ (i.e., the subgradients of $r$  produced by the dual method are exactly those produced by the primal method via~\eqref{eq:proximal-equivalence}).
    By assumption, $x_0=y_0$. Suppose for induction that $x_i=y_i$ for all $i=0,\dots,k$ and for all $i=0,\dots,k-1$ with $s(x_i)=0$ that $n_{i+1} = \frac{1}{\alpha_i}(x_i-\alpha_i g_{0}(x_i;\xi_i) -x_{i+1})$. Let $\bar g_i = g_0(y_i;\xi_i) + n_{i+1}$ if $y_i$ is feasible and $g_{s(y_i)}(y_i;\xi_i)$ otherwise. For each $i<k$, we claim $x_{i+1} =  x_i - \alpha_i \bar g_i$. If $x_i$ is infeasible, this is immediate. If $x_i$ is feasible, {\color{blue} rearrangement of our inductive hypothesis of on $n_{i+1}$ gives the claim}. Inductively, we conclude for $i<k$ that $ x_{i+1} - x_0 = - \sum_{t=0}^i \alpha_t \bar g_t. $

    By Lemma~\ref{lem:Mk-minimization}, $y_{k+1}$ is the unique solution to
    $\sum_{i=0}^k \lambda_i\left(\bar g_i + \mu(y_{k+1}-y_i) \right) + \bar\beta(y_{k+1}-y_0) = 0. $
    Rearranging and simplifying this, it follows that
    \begin{align*}
    y_{k+1} &= y_0 + \frac{\sum_{i=0}^k\lambda_i\mu(y_i-y_0)-\sum_{i=0}^k\lambda_i\bar g_i}{\sum_{i=0}^k\lambda_i\mu+\bar\beta}\\
    &= y_0 -\frac{\sum_{i=0}^{k} \lambda_{i}\mu\left( \sum_{t=0}^{i-1} \frac{\lambda_{t} \bar g_t}{\sum_{s=0}^{t}\lambda_{s}\mu + \bar \beta} \right) + \sum_{i=0}^{k}\lambda_i \bar g_i}{\sum_{i=0}^{k}\lambda_i\mu + \bar\beta}\\
