\begin{lemma}\label{lem:Mk-minimization}
    $y_{k+1}$ is the unique minimizer of $M^{(k)}(y)+\frac{\beta_k}{2}\|y-y_0\|_2^2$.
\end{lemma}

\begin{proof}
% {\color{blue}
First note that when $y_k$ is infeasible (and so $s(y_k)\neq 0$), $M^{(k)} = M^{(k-1)} + U^{(k)}$. From this, the result is immediate.
Now consider when $y_k$ is feasible (and so $s(y_k)=0$). Since $y_{k+1}$ is the unique minimizer of $M^{(k-1)}(y)+U^{(k)}(y)+\frac{\beta_k}{2}\|y-y_0\|_2^2$, the necessary and sufficient optimality condition ensures $y_{k+1}$ is the unique solution to
$$ 0 \in \nabla M^{(k-1)}(y_{k+1}) + \lambda_k(g_0(y_k; \xi_k) + \mu(y_{k+1}-y_k) + \partial r(y_{k+1})) + \beta_k(y_{k+1}-y_0) \ . $$
Rewriting this as $ \nabla M^{(k-1)}(y_{k+1}) + \lambda_k (g_0(y_k; \xi_k)+\mu(y_{k+1}-y_k)) + \beta_k(y_{k+1}-y_0) \in -\lambda_k \partial r(y_{k+1})$, we see that $n_{k+1}$ is the element of $\partial r(y_{k+1})$ certifying the minimization's optimality. Therefore
\begin{align*}
    0 &= \nabla M^{(k-1)}(y_{k+1}) + \lambda_k(g_0(y_k; \xi_k) + \mu(y_{k+1}-y_k)+n_{k+1}) + \beta_k(y_{k+1}-y_0)\\
    &= \nabla M^{(k)}(y_{k+1}) + \beta_k(y_{k+1}-y_0)
\end{align*}
and so $y_{k+1}$ is a the unique minimizer of $M^{(k)}(y)+\frac{\beta_k}{2}\|y-y_0\|_2^2$. 

\end{proof}

\begin{align*}
    0 &= \nabla M^{(k-1)}(y_{k+1}) + \lambda_k(g_0(y_k; \xi_k) + \mu(y_{k+1}-y_k)+n_{k+1}) + \beta_k(y_{k+1}-y_0)\\
    &= \nabla M^{(k)}(y_{k+1}) + \beta_k(y_{k+1}-y_0)
\end{align*}
and so $y_{k+1}$ is a the unique minimizer of $M^{(k)}(y)+\frac{\beta_k}{2}\|y-y_0\|_2^2$.

\begin{lemma}\label{lem:standard-quadratic}
    Any quadratic function of the form $Q(z) = c + \langle d,z\rangle + \frac{b}{2}\|z-\hat z\|^2_2$ with $b>0$ is equal to $Q(z) = \min Q + \frac{b}{2}\|z - \argmin Q\|^2_2$.
\end{lemma}

\begin{lemma}\label{lem:quad-calc}
    The sum of quadratics $Q_i(z) = a_i + \frac{b_i}{2}\|z-z_i\|_2^2$ for $i=1,2$ with $b_i > 0$ equals
    $$ (Q_1+Q_2)(z) = a_{1+2} + \frac{b_{1+2}}{2}\|z-z_{1+2}\|_2^2$$
    where $a_{1+2} = a_1 + a_2 + \frac{b_1b_2}{2(b_1+b_2)}\|z_1-z_2\|_2^2$, $b_{1+2} = b_1+b_2$, and $z_{1+2} = \frac{b_1}{b_1+b_2}z_1 + \frac{b_2}{b_1+b_2}z_2$.
\end{lemma}
